package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class TarArchiveOutputStream_putArchiveEntry_TriageGen2Test {

    private ByteArrayOutputStream out;
    private TarArchiveOutputStream tarOutputStream;

    @Before
    public void setUp() throws IOException {
        out = new ByteArrayOutputStream();
        tarOutputStream = new TarArchiveOutputStream(out);
    }

    @Test
    public void testPutArchiveEntry_NormalFile() throws IOException {
        String name = "short_name.txt";
        TarArchiveEntry entry = new TarArchiveEntry(name);
        entry.setSize(10);

        tarOutputStream.putArchiveEntry(entry);

        // Verify state changes
        // Since we can't easily access private fields without reflection, 
        // we rely on the fact that no exception was thrown and the method completed.
    }

    @Test
    public void testPutArchiveEntry_Directory() throws IOException {
        String name = "dir_name";
        TarArchiveEntry entry = new TarArchiveEntry(name);
        // TarArchiveEntry is a directory if size is 0 and we set it or via constructor logic

        tarOutputStream.putArchiveEntry(entry);
    }

    @Test
    public void testPutArchiveEntry_LongName_LongFileModeGNU() throws IOException {
        // Create a name longer than TarConstants.NAMELEN (100)
        StringBuilder longNameBuilder = new StringBuilder();
        for (int i = 0; i < TarConstants.NAMELEN + 10; i++) {
            longNameBuilder.append("a");
        }
        String longName = longNameBuilder.toString();

        TarArchiveEntry entry = new TarArchiveEntry(longName);
        entry.setSize(5);

        tarOutputStream.setLongFileMode(TarArchiveOutputStream.LONGFILE_GNU);

        // This should trigger the GNU LongLink logic
        tarOutputStream.putArchiveEntry(entry);

        // If it reaches here without exception, the branch was covered
    }

    @Test(expected = RuntimeException.class)
    public void testPutArchiveEntry_LongName_ThrowsException() throws IOException {
        StringBuilder longNameBuilder = new StringBuilder();
        for (int i = 0; i < TarConstants.NAMELEN + 10; i++) {
            longNameBuilder.append("a");
        }
        String longName = longNameBuilder.toString();

        TarArchiveEntry entry = new TarArchiveEntry(longName);

        // Default mode is typically not LONGFILE_GNU or LONGFILE_TRUNCATE
        // Ensuring it's a mode that triggers the exception
        tarOutputStream.setLongFileMode(0); 

        tarOutputStream.putArchiveEntry(entry);
    }

    @Test
    public void testPutArchiveEntry_LongName_TruncateMode() throws IOException {
        StringBuilder longNameBuilder = new StringBuilder();
        for (int i = 0; i < TarConstants.NAMELEN + 10; i++) {
            longNameBuilder.append("a");
        }
        String longName = longNameBuilder.toString();

        TarArchiveEntry entry = new TarArchiveEntry(longName);
        entry.setSize(5);

        tarOutputStream.setLongFileMode(TarArchiveOutputStream.LONGFILE_TRUNCATE);

        // This should bypass the exception branch
        tarOutputStream.putArchiveEntry(entry);
    }

    @Test
    public void testPutArchiveEntry_MockEntry() throws IOException {
        // Testing the branch where entry is passed but we want to ensure interaction
        // Note: The method casts to TarArchiveEntry, so we must provide a TarArchiveEntry or subclass
        TarArchiveEntry entry = new TarArchiveEntry("test.txt");
        entry.setSize(10);

        // We use a spy to verify the internal call to writeEntryHeader if possible, 
        // but since it's called on the object passed, we just ensure it works.
        tarOutputStream.putArchiveEntry(entry);
    }

    @Test
    public void testPutArchiveEntry_WithLargeSize() throws IOException {
        TarArchiveEntry entry = new TarArchiveEntry("large.bin");
        entry.setSize(1024 * 1024); // 1MB

        tarOutputStream.putArchiveEntry(entry);
    }
}
